<?php
declare(strict_types=1);
require_once __DIR__ . '/app.php';
$user = require_auth();
require_once __DIR__ . '/controls_domain.php';
require_control_writer($user);
$geo = geography_rows($user); $types = control_checklists();
$editId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); $editing = is_int($editId) && $editId > 0;
$existing = null; $metadataValues = []; $answerValues = []; $controllerValues = [];
if ($editing) {
    [$scope, $scopeParams] = scope_clause($user, 'cr'); $stmt = db()->prepare("SELECT cr.* FROM control_reports cr WHERE cr.id=:id AND {$scope} LIMIT 1");
    $stmt->execute([':id' => $editId] + $scopeParams); $existing = $stmt->fetch();
    if (!$existing) { http_response_code(404); exit('Rapport introuvable ou non autorisé.'); }
    $decoded = json_decode((string)$existing['metadata_json'], true); $metadataValues = is_array($decoded) ? $decoded : [];
    $regionId = (int)$existing['region_id']; $provinceId = (int)$existing['province_id']; $type = (string)$existing['inspection_type']; $farmId = (int)($existing['farm_id'] ?? 0);
    $stmt = db()->prepare('SELECT item_key, answer, observation FROM control_report_answers WHERE report_id=:id'); $stmt->execute([':id' => $editId]);
    foreach ($stmt->fetchAll() as $row) $answerValues[$row['item_key']] = ['status' => $row['answer'] ?? '', 'observation' => $row['observation'] ?? ''];
    $stmt = db()->prepare('SELECT full_name, function_title, signature_text FROM control_report_controllers WHERE report_id=:id ORDER BY sort_order, id'); $stmt->execute([':id' => $editId]);
    $controllerValues = array_map(static fn(array $row): array => ['name' => $row['full_name'], 'function' => $row['function_title'], 'signature_text' => $row['signature_text']], $stmt->fetchAll());
} else {
    $regionId = has_global_scope($user) ? (int)($_GET['region_id'] ?? 0) : (int)($user['region_id'] ?? 0);
    $provinceId = has_province_scope($user) ? (int)$user['province_id'] : (int)($_GET['province_id'] ?? 0);
    $type = (string)($_GET['type'] ?? ''); if (!isset($types[$type])) $type = '';
    $farmId = (int)(filter_var($_GET['farm_id'] ?? null, FILTER_VALIDATE_INT) ?: 0);
}
$geoChoice = null; foreach ($geo['rows'] as $row) if ((int)$row['region_id'] === $regionId && (int)$row['province_id'] === $provinceId) { $geoChoice = $row; break; }
if (!$geoChoice) { http_response_code(400); exit('Province non autorisée pour votre profil.'); }
$farms = $type === 'transport' ? [] : list_farms($user, ['region_id' => (string)$regionId, 'province_id' => (string)$provinceId], 'name', 'global');
$selectedFarm = null;
if ($type !== '' && $type !== 'transport' && $farmId > 0) foreach ($farms as $farm) {
    $matches = match ($type) { 'chair' => $farm['farm_type'] === 'Chair', 'reproducteurs' => $farm['farm_type'] === 'Reproducteurs', 'pondeuses' => $farm['farm_type'] === 'Pondeuses', default => false };
    if ((int)$farm['id'] === $farmId && $matches) { $selectedFarm = $farm; break; }
}
if ($editing && $type !== 'transport' && !$selectedFarm) $selectedFarm = ['id' => $farmId, 'farm_name' => $existing['unit_name'], 'authorization_number' => $existing['authorization_number'], 'owner_name' => $existing['owner_name']];
$owners = []; if ($type !== 'transport') { foreach ($farms as $farm) { $owner = trim((string)($farm['owner_name'] ?? '')); if ($owner !== '') $owners[$owner] = $owner; } asort($owners, SORT_NATURAL | SORT_FLAG_CASE); }
$phase = $editing || ($geoChoice && ($type === 'transport' || $selectedFarm)) ? 'form' : 'type'; $reportListPage = $type === 'transport' ? 'vehicle_controls.php' : 'controls.php'; $reportError = isset($_GET['error']) ? 'Vérifiez les informations et réessayez.' : ''; $flash = take_flash();
$vehiclePhotoViewsSaved=[]; $unitPhotoSlotsSaved=[]; $photoStorageMissing=false;
if ($phase==='form') {
    try {
        if ($type==='transport') {
            $photoStmt=db()->prepare($editing?'SELECT view_key FROM control_report_photos WHERE report_id=:id':'SELECT view_key FROM control_report_photos WHERE 1=0');
            if ($editing) $photoStmt->execute([':id'=>(int)$editId]); else $photoStmt->execute();
            foreach ($photoStmt->fetchAll(PDO::FETCH_COLUMN) as $viewKey) $vehiclePhotoViewsSaved[(string)$viewKey]=true;
        } else {
            $photoStmt=db()->prepare($editing?'SELECT photo_slot FROM control_report_unit_photos WHERE report_id=:id':'SELECT photo_slot FROM control_report_unit_photos WHERE 1=0');
            if ($editing) $photoStmt->execute([':id'=>(int)$editId]); else $photoStmt->execute();
            foreach ($photoStmt->fetchAll(PDO::FETCH_COLUMN) as $slot) $unitPhotoSlotsSaved[(int)$slot]=true;
        }
    } catch (PDOException $exception) {
        $message=strtolower($exception->getMessage());
        $tableName=$type==='transport'?'control_report_photos':'control_report_unit_photos';
        $photoStorageMissing=str_contains($message,$tableName)&&(str_contains($message,'no such table')||str_contains($message,"doesn't exist")||str_contains($message,'does not exist'));
        if (!$photoStorageMissing) throw $exception;
    }
}
function control_field_impl(array $field, string $key, string $value = ''): string {
    [$label, $kind] = $field; $id = 'meta_' . preg_replace('/[^a-z0-9_]/i', '_', $key); $html = '<label class="control-field" for="' . e($id) . '">' . e($label);
    if (str_starts_with($kind, 'select:')) {
        $options = explode(',', substr($kind, 7)); $labels = ['poussin'=>'Poussin(s)','eggs'=>'Œufs à couver (OAC)','live_poultry'=>'Volailles vivantes','poussiniere'=>'Poussinière','production'=>'Production'];
        $html .= '<select id="' . e($id) . '" name="metadata[' . e($key) . ']"' . ($key === 'products' ? ' required' : '') . '><option value="">Choisir…</option>';
        foreach ($options as $option) $html .= '<option value="' . e($option) . '" ' . ($value === $option ? 'selected' : '') . '>' . e($labels[$option] ?? ucfirst($option)) . '</option>'; $html .= '</select>';
    } elseif ($kind === 'plate') {
        $parts = explode('-', $value); $serial = $parts[0] ?? ''; $letter = moroccan_registration_latin_letter($parts[1] ?? ''); $code = $parts[2] ?? '';
        $letters = moroccan_registration_letters();
        $html .= '<span class="plate-fields"><input id="plate-serial" name="metadata[registration_serial]" type="text" inputmode="numeric" pattern="[0-9]{5}" minlength="5" maxlength="5" placeholder="XXXXX" value="' . e($serial) . '" required aria-label="Cinq chiffres d’immatriculation"><span aria-hidden="true">—</span><select id="plate-letter" name="metadata[registration_letter]" required aria-label="Lettre d’immatriculation en alphabet français"><option value="">Lettre</option>';
        foreach ($letters as $option) $html .= '<option value="' . e($option) . '" ' . ($letter === $option ? 'selected' : '') . '>' . e($option) . '</option>';
        $html .= '</select><span aria-hidden="true">—</span><select id="plate-code" name="metadata[registration_code]" required aria-label="Code provincial"><option value="">Code</option>';
        for ($i=1;$i<=89;$i++) { $option=sprintf('%02d',$i); $html .= '<option value="'.$option.'" '.($code===$option?'selected':'').'>'.$option.'</option>'; }
        $html .= '</select></span><input id="meta_registration" name="metadata[registration]" type="hidden" value="' . e($value) . '">';
    } else { $inputType = match ($kind) { 'date'=>'date','number'=>'number',default=>'text' }; $html .= '<input id="' . e($id) . '" name="metadata[' . e($key) . ']" type="' . $inputType . '" maxlength="500" value="' . e($value) . '"' . ($key==='inspection_date'||$key==='authorization_date'?' required':'') . '>'; }
    return $html . '</label>';
}
?>
