<?php if (!$editing&&$geoChoice): ?><section class="card control-step"><h2>2. Type de contrôle<?= $type==='transport'?'':' et unité avicole' ?></h2><p class="help"><?= $type==='transport'?'Le contrôle de transport est indépendant des unités avicoles et de leurs autorisations.':'Choisissez le type de contrôle puis l’unité avicole concernée.' ?></p><form method="get" action="control_form.php" id="unit-form" class="formgrid"><input type="hidden" name="region_id" value="<?=$regionId?>"><input type="hidden" name="province_id" value="<?=$provinceId?>"><label>Type de contrôle<select name="type" id="control-type" required><option value="">Choisir…</option><?php foreach($types as $key=>$template): if($key==='transport') continue; ?><option value="<?=e($key)?>" <?=$type===$key?'selected':''?>><?=e($template['label'])?></option><?php endforeach; ?></select></label><?php if($type!=='transport'): ?><label id="farm-select-label">Unité<select name="farm_id" id="farm-choice" required><option value="">Choisir l’unité…</option><?php foreach($farms as $farm): ?><option value="<?=(int)$farm['id']?>" data-farm-type="<?=e($farm['farm_type'])?>" <?=$selectedFarm&&(int)$selectedFarm['id']===(int)$farm['id']?'selected':''?>><?=e($farm['farm_name'])?><?=!empty($farm['owner_name'])?' — '.e($farm['owner_name']):''?> (<?=e($farm['farm_type'])?>)</option><?php endforeach; ?></select></label><?php endif; ?><button class="btn" type="submit">Continuer vers la fiche</button></form><?php if(!$farms&&$type!=='transport'): ?><p class="flash error">Aucune unité enregistrée dans cette province. Le contrôle transport reste disponible sans unité.</p><?php endif; ?></section><?php endif; ?>
