<?php foreach($template['fields'] as $key=>$field): [$label,$kind]=$field; if($kind==='readonly'){$value=$key==='unit_name'?($selectedFarm['farm_name']??''):($key==='authorization_number'?($selectedFarm['authorization_number']??''):'');if($key!=='society_name')echo '<label class="control-field">'.e($label).'<input value="'.e($value).'" readonly></label>';}elseif($kind==='owner'){ ?><label class="control-field">Propriétaire<select name="owner_name" id="owner-choice"><option value="">Choisir le propriétaire…</option><?php foreach($owners as $owner): ?><option value="<?=e($owner)?>" <?=($selectedFarm['owner_name']??'')===$owner?'selected':''?>><?=e($owner)?></option><?php endforeach; ?></select></label><label class="control-field">Société / propriétaire<input value="<?=e($selectedFarm['owner_name']??'')?>" readonly></label><?php }else{$value=match($key){'inspection_date'=>$existing['inspection_date']??date('Y-m-d'),'authorization_date'=>$metadataValues['authorization_date']??($existing['inspection_date']??date('Y-m-d')),'authorization_number'=>$existing['authorization_number']??'','owner_name'=>$existing['owner_name']??'',default=>$metadataValues[$key]??''};if(!$isTransport&&in_array($key,['authorization_number','owner_name'],true))continue;echo control_field_impl($field,$key,(string)$value);} endforeach; ?></div>
