ass="vehicle-photo-grid"><?php foreach(vehicle_photo_views() as $view=>$label): ?><div class="vehicle-photo-card"><strong><?=e($label)?></strong><?php if(isset($vehiclePhotoViewsSaved[$view])): ?><a href="control_photo.php?id=<?=$editId?>&amp;view=<?=e($view)?>" target="_blank" rel="noopener"><img class="photo-saved-thumb" src="control_photo.php?id=<?=$editId?>&amp;view=<?=e($view)?>" alt="Photo enregistrée — <?=e($label)?>"></a><span><input type="checkbox" name="delete_vehicle_photos[]" value="<?=e($view)?>"> Supprimer cette photo</span><?php endif; ?><input id="vehicle-photo-<?=e($view)?>" class="photo-input" data-preview="vehicle-photo-preview-<?=e($view)?>" type="file" name="vehicle_photos[<?=e($view)?>]" accept="image/jpeg,image/png,image/webp" capture="environment" aria-label="Prendre ou choisir une photo : <?=e($label)?>"><span>Prendre une photo ou choisir/remplacer un fichier</span><img id="vehicle-photo-preview-<?=e($view)?>" alt="Aperçu — <?=e($label)?>" hidden></div><?php endforeach; ?></div><p class="photo-upload-status help" aria-live="polite"></p><?php endif; ?></section><?php elseif($photoStorageMissing): ?><section class="vehicle-photos-section" id="unit-photos"><h3>Photos de la visite</h3><p class="flash error">Importez <a href="database/profile_roles_and_unit_photos.sql" download>database/profile_roles_and_unit_photos.sql</a> pour activer les photos des rapports de visite.</p></section><?php else: ?><section class="vehicle-photos-section" id="unit-photos"><div class="vehicle-photos-heading"><div><h3>Photos de la visite de l’unité (facultatives)</h3><p class="help">Jusqu’à 6 photos, prises directement avec le smartphone ou choisies sur ordinateur. JPEG, PNG ou WebP, 2 Mo par photo et 8 Mo au total. Les images existantes sont conservées, remplacées par leur emplacement, ou supprimées si la case correspondante est cochée.</p></div><?php if($editing): ?><a class="btn secondary" href="control_unit_photos.php?id=<?=$editId?>">Visualiser les photos</a><?php endif; ?></div><div class="vehicle-photo-grid unit-visit-photo-grid"><?php for($slot=1;$slot<=6;$slot++): ?><div class="vehicle-photo-card unit-visit-photo-card"><strong>Photo <?=$slot?></strong><?php if(isset($unitPhotoSlotsSaved[$slot])): ?><a href="control_unit_photo.php?id=<?=$editId?>&amp;slot=<?=$slot?>" target="_blank" rel="noopener"><img class="photo-saved-thumb" src="control_unit_photo.php?id=<?=$editId?>&amp;slot=<?=$slot?>" alt="Photo de visite <?=$slot?>"></a><span><input type="checkbox" name="delete_unit_photos[]" value="<?=$slot?>"> Supprimer cette photo</span><?php endif; ?><input id="unit-photo-<?=$slot?>" class="photo-input" data-preview="unit-photo-preview-<?=$slot?>" type="file" name="unit_photos[<?=$slot?>]" accept="image/jpeg,image/png,image/webp" capture="environment" aria-label="Prendre ou choisir la photo <?=$slot?>"><span>Prendre une photo ou choisir/remplacer</span><img id="unit-photo-preview-<?=$slot?>" alt="Aperçu de la photo <?=$slot?>" hidden></div><?php endfor; ?></div><p class="photo-upload-status help" aria-live="polite"></p></section><?php endif; ?><p class="actions"><button class="btn" type="submit"><?= $editing?'Enregistrer les modifications':'Enregistrer et générer le rapport' ?></button><a class="btn secondary" href="<?=e($reportListPage)?>">Annuler</a></p></form></section><?php endif; ?></main>
