const region=document.getElementById('region'),province=document.getElementById('province');function filterProvinces(){if(!region||!province)return;for(const option of province.options){if(!option.value)continue;option.hidden=!!region.value&&option.dataset.region!==region.value;}if(province.selectedOptions[0]?.hidden)province.value='';}if(region&&province){region.addEventListener('change',filterProvinces);filterProvinces();}
const typeSelect=document.getElementById('control-type'),farmLabel=document.getElementById('farm-select-label'),farmSelect=document.getElementById('farm-choice');function filterFarmChoices(){if(!typeSelect)return;const type=typeSelect.value,transport=type==='transport';if(farmLabel)farmLabel.hidden=transport;if(farmSelect){farmSelect.required=!transport;for(const option of farmSelect.options){if(!option.value)continue;option.hidden=transport||!({chair:'Chair',reproducteurs:'Reproducteurs',pondeuses:'Pondeuses'}[type]===option.dataset.farmType);if(option.hidden&&option.selected)farmSelect.value='';}}}if(typeSelect){typeSelect.addEventListener('change',filterFarmChoices);filterFarmChoices();}
const productSelect=document.getElementById('meta_products');function filterProductSections(){if(!productSelect)return;for(const row of document.querySelectorAll('[data-product-section]')){const section=row.dataset.productSection,active=section==='common'||section===productSelect.value;row.hidden=false;row.classList.toggle('product-inactive',!active);row.setAttribute('aria-disabled',String(!active));for(const control of row.querySelectorAll('input,textarea,select,button'))control.disabled=!active;}}if(productSelect){productSelect.addEventListener('change',filterProductSections);filterProductSections();}
const serial=document.getElementById('plate-serial'),letter=document.getElementById('plate-letter'),code=document.getElementById('plate-code'),plate=document.getElementById('meta_registration');function setPlate(){if(plate)plate.value=[serial?.value||'',letter?.value||'',code?.value||''].join('-');}if(serial){const cleanSerial=()=>{serial.value=serial.value.replace(/[^0-9]/g,'').slice(0,5);setPlate();};serial.value=serial.value.replace(/[^0-9]/g,'').slice(0,5);serial.addEventListener('input',cleanSerial);serial.addEventListener('change',cleanSerial);}for(const el of [letter,code])if(el){el.addEventListener('input',setPlate);el.addEventListener('change',setPlate);}
const addButton=document.getElementById('add-controller'),controllerList=document.getElementById('controllers-list');if(addButton&&controllerList)addButton.addEventListener('click',()=>{const index=Date.now();const row=document.createElement('div');row.className='controller-row';row.innerHTML=`<label>Nom et prénom<input name="controllers[${index}][name]" maxlength="190" required></label><label>Fonction<input name="controllers[${index}][function]" maxlength="190"></label><label>Signature<input name="controllers[${index}][signature_text]" maxlength="255"></label><button type="button" class="btn danger remove-controller">Retirer</button>`;row.querySelector('.remove-controller').addEventListener('click',()=>row.remove());controllerList.append(row);});document.querySelectorAll('.remove-controller').forEach(button=>button.addEventListener('click',()=>button.closest('.controller-row').remove()));
const photoForm=document.getElementById('control-form'),photoInputs=[...document.querySelectorAll('.photo-input')],photoStatus=document.querySelector('.photo-upload-status');for(const input of photoInputs)input.addEventListener('change',()=>{const file=input.files?.[0],preview=document.getElementById(input.dataset.preview);if(!file||!preview)return;if(preview.dataset.url)URL.revokeObjectURL(preview.dataset.url);preview.dataset.url=URL.createObjectURL(file);preview.src=preview.dataset.url;preview.hidden=false;input.closest('.vehicle-photo-card')?.classList.add('has-photo');});async function compressPhoto(file){if(file.size<=900000)return file;if(typeof createImageBitmap!=='function'||typeof DataTransfer!=='function')throw new Error('Votre navigateur ne permet pas de réduire automatiquement cette image. Choisissez une image de moins de 900 Ko.');const bitmap=await createImageBitmap(file);try{let scale=Math.min(1,1600/bitmap.width,1600/bitmap.height);for(let attempt=0;attempt<4;attempt++){const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d',{alpha:false});context.drawImage(bitmap,0,0,canvas.width,canvas.height);for(const quality of [0.82,0.72,0.62]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=900000)return new File([blob],'photo-visite.jpg',{type:'image/jpeg'});}scale*=0.78;}throw new Error('Impossible de réduire cette image sous 900 Ko.');}finally{bitmap.close?.();}}if(photoForm&&photoInputs.length)photoForm.addEventListener('submit',async event=>{event.preventDefault();const buttons=[...photoForm.querySelectorAll('button[type="submit"]')];buttons.forEach(button=>button.disabled=true);if(photoStatus)photoStatus.textContent='Préparation des photos…';try{for(const input of photoInputs){const file=input.files?.[0];if(!file)continue;const ready=await compressPhoto(file);if(ready.size>2097152)throw new Error('Chaque photo doit faire au maximum 2 Mo.');if(ready!==file){const transfer=new DataTransfer();transfer.items.add(ready);input.files=transfer.files;}}if(photoStatus)photoStatus.textContent='Enregistrement du rapport et des photos…';photoForm.submit();}catch(error){if(photoStatus)photoStatus.textContent=error.message||'Une photo ne peut pas être préparée.';buttons.forEach(button=>button.disabled=false);}});
</script><script src="assets/idle-timeout.js" defer></script></body></html>
